/* ---------- Grammar Grove, grade 5 (L.5.1, L.5.2, L.5.3) ---------- */
BANK3.grammar5=[
 ['conjprep','In <i>"The cat hid under the bed,"</i> which word is a <b>preposition</b>?','under',['cat','hid','bed'],'A preposition shows where or when: under, over, after, during.','<b>Under</b> shows where the cat hid.'],
 ['conjprep','Which word is an <b>interjection</b>?','Wow',['quickly','table','because'],'An interjection shows strong feeling and often has an exclamation point.','<b>Wow!</b> shows surprise.'],
 ['conjprep','In <i>"We stayed inside because it rained,"</i> what kind of word is <b>because</b>?','conjunction',['preposition','interjection','adjective'],'It joins two ideas.','<b>Because</b> is a conjunction joining two ideas.'],
 ['conjprep','Which sentence uses a <b>prepositional phrase</b>?','We ate lunch after the game.',['We ate lunch.','Lunch was good.','We were hungry.'],'Look for a group of words starting with a preposition.','<b>After the game</b> is a prepositional phrase.'],
 ['conjprep','Choose the interjection that fits: <i>"___! That pan is hot!"</i>','Ouch',['Under','And','Slowly'],'Which word shows a sudden feeling?','<b>Ouch!</b> shows sudden pain.'],
 ['conjprep','Which word is a <b>preposition</b> in <i>"During the storm, the lights flickered"</i>?','During',['storm','lights','flickered'],'Which word shows when?','<b>During</b> tells when.'],
 ['perfect','Which sentence uses the <b>present perfect</b> tense?','I have finished my homework.',['I finished my homework.','I will finish my homework.','I had finished my homework.'],'Present perfect uses has/have + past participle.','<b>Have finished</b> is present perfect.'],
 ['perfect','Which sentence uses the <b>past perfect</b> tense?','The train had left before we arrived.',['The train left.','The train has left.','The train will have left.'],'Past perfect uses had + past participle.','<b>Had left</b> is past perfect.'],
 ['perfect','Which sentence uses the <b>future perfect</b> tense?','By June, she will have read ten books.',['She read ten books.','She has read ten books.','She had read ten books.'],'Future perfect uses will have + past participle.','<b>Will have read</b> is future perfect.'],
 ['perfect','Choose the verb: <i>"By the time Dad got home, we ___ dinner."</i>','had cooked',['have cooked','will have cooked','cook'],'One past action happened before another past action.','<b>Had cooked</b>: the cooking was finished before Dad got home.'],
 ['perfect','Choose the verb: <i>"Maria ___ in California since 2020."</i>','has lived',['had lived','will have lived','lives since'],'"Since" with something still true now uses has/have.','<b>Has lived</b>: she still lives there.'],
 ['perfect','Choose the verb: <i>"By next summer, the bridge ___."</i>','will have been finished',['has been finished','had been finished','was finished'],'Something that will be done before a future time.','<b>Will have been finished</b> is future perfect.'],
 ['tense','Which sentence has an <b>incorrect shift</b> in verb tense?','Yesterday I walk to the park and played soccer.',['Yesterday I walked to the park and played soccer.','Today I walk to the park and play soccer.','Tomorrow I will walk to the park and play soccer.'],'The verbs should match the time.','<b>"Yesterday I walk"</b> shifts tense; it should be "walked".'],
 ['tense','Fix the tense shift: <i>"She opens the box and found a puppy."</i>','She opened the box and found a puppy.',['She opens the box and founded a puppy.','She opening the box and found a puppy.','She open the box and find a puppy.'],'Both verbs should be in the same time.','<b>Opened ... found</b>: both past.'],
 ['tense','Which verb best shows the order of events? <i>"After the guests ___, we cleaned up."</i>','had left',['leave','will leave','are leaving'],'The leaving happened before the cleaning.','<b>Had left</b> shows it happened first.'],
 ['tense','Which sentence correctly shows a <b>future</b> action?','The game will start at noon.',['The game started at noon.','The game starts yesterday.','The game had started tomorrow.'],'Future uses will.','<b>Will start</b> is future.'],
 ['tense','Choose the verb: <i>"Every summer, my family ___ to the lake."</i>','goes',['went tomorrow','will went','going'],'"Every summer" is a habit: present tense.','<b>Goes</b> shows something that happens regularly.'],
 ['tense','Which sentence keeps the tense the same?','The dog barked, ran in circles and jumped.',['The dog barked, runs in circles and jumped.','The dog barks, ran in circles and jumps.','The dog barked, runs in circles and jumps.'],'Check every verb.','<b>Barked, ran, jumped</b>: all past.'],
 ['correl','Choose the correct pair: <i>"___ my sister ___ my brother likes broccoli."</i>','Neither ... nor',['Either ... nor','Neither ... or','Both ... or'],'Correlative conjunctions come in pairs.','<b>Neither ... nor</b> go together.'],
 ['correl','Choose the correct pair: <i>"You can ___ walk ___ ride your bike."</i>','either ... or',['neither ... or','both ... or','either ... nor'],'Either goes with or.','<b>Either ... or</b>.'],
 ['correl','Choose the correct pair: <i>"She is ___ smart ___ kind."</i>','both ... and',['both ... or','either ... and','neither ... and'],'Both goes with and.','<b>Both ... and</b>.'],
 ['correl','Choose the correct pair: <i>"___ only did we win, ___ we also set a record."</i>','Not ... but',['Not ... and','Either ... but','Both ... but'],'Not only ... but also.','<b>Not only ... but also</b>.'],
 ['correl','Which sentence uses correlative conjunctions correctly?','Whether it rains or shines, we will play.',['Whether it rains nor shines, we will play.','Either it rains and shines, we will play.','Both it rains or shines, we will play.'],'Whether goes with or.','<b>Whether ... or</b> is correct.'],
 ['correl','Which pair of words are correlative conjunctions?','either ... or',['and ... the','because ... so','under ... over'],'They work as a pair to join ideas.','<b>Either ... or</b> works as a pair.'],
 ['commas','Which sentence uses commas in a series correctly?','We packed apples, cheese, crackers and juice.',['We packed apples cheese, crackers and juice.','We packed, apples, cheese, crackers and juice.','We packed apples cheese crackers, and juice.'],'Put commas between items in a list.','<b>Apples, cheese, crackers and juice</b>.'],
 ['commas','Where does the comma go? <i>"After the long hike we rested."</i>','After the long hike, we rested.',['After, the long hike we rested.','After the long, hike we rested.','After the long hike we, rested.'],'Put a comma after an introductory phrase.','<b>After the long hike,</b> is the introduction.'],
 ['commas','Which sentence uses a comma correctly with <b>yes</b> or <b>no</b>?','Yes, I would like more soup.',['Yes I, would like more soup.','Yes I would like, more soup.','Yes I would like more, soup.'],'Put a comma after yes or no at the start.','<b>Yes,</b> is followed by a comma.'],
 ['commas','Which sentence correctly uses a comma to address someone directly?','Sam, can you pass the salt?',['Sam can, you pass the salt?','Sam can you pass, the salt?','Sam can you pass the salt,?'],'Set off the name of the person you are talking to.','<b>Sam,</b> is set off with a comma.'],
 ['commas','Which sentence has a correctly punctuated <b>tag question</b>?','It is cold today, isn\'t it?',['It is cold today isn\'t it?','It is, cold today isn\'t it?','It is cold, today isn\'t it?'],'A comma comes before the tag question.','<b>..., isn\'t it?</b>'],
 ['commas','Where does the comma go? <i>"Well I think you are right."</i>','Well, I think you are right.',['Well I, think you are right.','Well I think, you are right.','Well I think you, are right.'],'Put a comma after an introductory word.','<b>Well,</b> is an introductory word.'],
 ['titles5','How should you show the title of a <b>book</b> when you write by hand?','Underline it',['Put it in quotation marks','Write it in all capitals','Put it in parentheses'],'Long works (books, movies) are underlined by hand or in italics when typed.','Book titles are <b>underlined</b> (or italic when typed).'],
 ['titles5','How should you show the title of a <b>song</b> or <b>poem</b>?','Put it in quotation marks',['Underline it','Use italics','Write it in all capitals'],'Short works go in quotation marks.','Song and poem titles go in <b>quotation marks</b>.'],
 ['titles5','Which is written correctly?','We sang "This Land Is Your Land" in class.',['We sang This Land Is Your Land in class.','We sang (This Land Is Your Land) in class.','We sang THIS LAND IS YOUR LAND in class.'],'A song is a short work.','A song title goes in <b>quotation marks</b>.'],
 ['titles5','A typed report mentions the movie <i>The Wild Robot</i>. How is the movie title shown?','in italics',['in quotation marks','in bold','in parentheses'],'Movies are long works.','Typed long-work titles go in <b>italics</b>.'],
 ['titles5','Which title should go in quotation marks?','a short story',['a novel','a magazine','a movie'],'Short works use quotation marks.','<b>A short story</b> goes in quotation marks.'],
 ['titles5','Which title should be underlined or in italics?','a newspaper',['a chapter of a book','a poem','a song'],'Whole long works are underlined or italic.','<b>A newspaper</b> is a whole work.'],
 ['spell5','Which word is spelled correctly?','necessary',['neccessary','necessery','nessesary'],'One c, two s\'s.','<b>Necessary</b>: one c, double s.'],
 ['spell5','Which word is spelled correctly?','separate',['seperate','separete','seprate'],'There\'s "a rat" in separate.','<b>Separate</b>.'],
 ['spell5','Which word is spelled correctly?','receive',['recieve','receeve','resieve'],'i before e, except after c.','<b>Receive</b>: e before i after c.'],
 ['spell5','Which word is spelled correctly?','environment',['enviroment','envirnment','envyronment'],'Don\'t forget the n before -ment.','<b>Environment</b>.'],
 ['spell5','Which word is spelled correctly?','government',['goverment','govenment','guvernment'],'Govern + ment.','<b>Government</b>.'],
 ['spell5','Which word is spelled correctly?','definitely',['definately','definitly','defenitely'],'It comes from "finite".','<b>Definitely</b>.'],
 ['combine','Combine the sentences: <i>"The wolf howled. The wolf was lonely."</i>','The lonely wolf howled.',['The wolf howled lonely wolf.','Howled the wolf lonely.','The wolf was howled lonely.'],'Move the describing word in front of the noun.','<b>The lonely wolf howled.</b>'],
 ['combine','Make this sentence shorter without losing meaning: <i>"The big, large, huge elephant walked slowly."</i>','The huge elephant walked slowly.',['The elephant walked.','The big large elephant walked slowly.','Elephant slowly.'],'Remove words that repeat the same idea.','<b>The huge elephant walked slowly.</b>'],
 ['combine','Expand the sentence with details: <i>"The bird sang."</i>','The tiny bird sang a cheerful song at sunrise.',['The bird sang sang.','Bird.','The bird did sing.'],'Add who, what, when or how.','<b>The tiny bird sang a cheerful song at sunrise.</b>'],
 ['combine','Combine: <i>"We went to the museum. We saw dinosaur bones."</i>','At the museum, we saw dinosaur bones.',['We went museum saw bones.','Museum, dinosaur, bones.','We went to the museum we saw dinosaur bones.'],'Use a phrase to join the ideas smoothly.','<b>At the museum, we saw dinosaur bones.</b>'],
 ['combine','Combine: <i>"Leo plays piano. Leo plays guitar."</i>','Leo plays piano and guitar.',['Leo plays piano Leo plays guitar.','Leo piano guitar.','Plays Leo piano and plays guitar.'],'Join the two things he plays.','<b>Leo plays piano and guitar.</b>'],
 ['combine','Which sentence is the clearest combination of <i>"It was late. We were tired. We went home."</i>?','It was late and we were tired, so we went home.',['It was late we were tired we went home.','Late, tired, home.','We went home, it was late, we were tired, so.'],'Show how the ideas connect.','<b>It was late and we were tired, so we went home.</b>'],
 ['dialect','A story character says, <i>"Y\'all come back now!"</i> Why might an author write it this way?','to show how the character talks where they live',['because the author made a mistake','to make the story shorter','to confuse the reader'],'Authors show dialects to make characters real.','It shows the character\'s <b>regional way of speaking</b>.'],
 ['dialect','Which is the <b>formal</b> way to write <i>"gonna"</i> in a report?','going to',['gona','gunna','go to'],'Formal writing avoids casual spellings.','Use <b>going to</b>.'],
 ['dialect','In a story, a pirate says, <i>"Ahoy, matey!"</i> What does this language add?','It helps the reader hear the character\'s voice.',['It explains a science fact.','It is a mistake.','It makes the story a poem.'],'Think about how characters sound.','It gives the pirate <b>a real voice</b>.'],
 ['dialect','Which sentence would fit best in a <b>formal letter</b> to the mayor?','I am writing to ask for a new crosswalk on Main Street.',['Hey, we need a crosswalk, ya know?','Crosswalk pls!','Yo mayor, fix the street.'],'Formal letters are polite and complete.','<b>I am writing to ask for a new crosswalk...</b>'],
 ['dialect','Why do authors sometimes write dialogue that is not "standard" English?','to show how real people from different places speak',['because they do not know the rules','to make the story longer','to hide the meaning'],'Characters come from many places.','To show <b>how real people speak</b>.'],
 ['dialect','Which word would you <b>replace</b> in a school report? <i>"The experiment was super awesome."</i>','super awesome',['The','experiment','was'],'Pick the casual words.','<b>Super awesome</b> is casual; try "very successful".']
];

