/* ---------- Bookworm Bay, grade 5: short passages ---------- */
const PASS5=[
 {t:'The Inventor\'s Notebook',p:['Twelve-year-old Rosa filled every page of her notebook with sketches of machines that didn\'t exist yet.','Her teacher called them "daydreams," but Rosa called them "plans."','When the town\'s water pump broke, Rosa flipped to page 34, where she had drawn a pump powered by a bicycle.','By Saturday, the whole neighborhood was taking turns pedaling, and water flowed again.'],
  q:[['How does the teacher\'s view of the sketches differ from Rosa\'s?','The teacher sees them as daydreams; Rosa sees them as real plans.',['They both think the sketches are useless.','The teacher wants to sell them.','Rosa thinks they are jokes.'],'Compare the two words in quotation marks.','"Daydreams" vs. "plans": the teacher doubts them, but <b>Rosa believes in them</b>.'],
     ['Which theme does the story suggest?','Imagination can solve real problems.',['Teachers are always right.','Bicycles are faster than cars.','Water pumps break often.'],'What happened because of Rosa\'s sketch?','Her imagined pump fixed a real problem: <b>imagination can solve real problems</b>.'],
     ['What can you infer about Rosa?','She is creative and prepared.',['She is lazy.','She dislikes her town.','She cannot draw.'],'She had a plan ready when the pump broke.','She had already designed a solution, so she is <b>creative and prepared</b>.']]},
 {t:'Two Accounts of the First Day of School',p:['<b>Account 1, from Jamal\'s diary:</b> I was so nervous my hands were sweaty. But when Ms. Ortiz smiled and said my name right, I felt like I belonged.','<b>Account 2, from the school newsletter:</b> The first day of school welcomed 450 students. Teachers greeted families at the gate, and classes began at 8:15.'],
  q:[['How are the two accounts different?','Account 1 shares feelings; Account 2 reports facts.',['Both share feelings.','Both report only numbers.','Account 2 is a poem.'],'Who wrote each one, and why?','The diary gives <b>personal feelings</b>; the newsletter gives <b>facts</b>.'],
     ['What information appears <b>only</b> in Account 2?','how many students came and when classes began',['how Jamal felt','his teacher\'s name','that he belonged'],'Look for numbers.','Only the newsletter gives <b>450 students and 8:15</b>.'],
     ['Why might Account 1 be called a firsthand account?','It was written by someone who experienced the event.',['It was written first.','It is shorter.','It has numbers.'],'Who lived through it?','Jamal <b>experienced it himself</b>.']]},
 {t:'The Water Strider',p:['A water strider can walk on top of a pond without sinking.','Its long, thin legs spread its weight over the water\'s surface.','Tiny hairs on its legs trap air, which keeps the legs from getting wet.','Because of these adaptations, the insect can skate across the water to catch food.'],
  q:[['What is the main idea?','Special body features let water striders walk on water.',['Ponds are dangerous.','Insects cannot swim.','Water striders are the fastest insects.'],'What do all the details explain?','Its legs and hairs <b>let it walk on water</b>.'],
     ['How do the tiny hairs help?','They trap air so the legs stay dry.',['They help it see.','They make it heavier.','They keep it warm.'],'Look at the third sentence.','The hairs <b>trap air</b>.'],
     ['Which word signals a cause-and-effect relationship in the passage?','Because',['Tiny','can','across'],'Look for a signal word.','<b>Because</b> connects the adaptations to the result.']]},
 {t:'The Mountain (a poem)',p:['The mountain does not hurry,','It does not fret or race;','It wears the snow in winter','With patience on its face.','','And when the summer finds it,','It hums with bees and streams;','The mountain keeps on standing,','A giant full of dreams.'],lines:true,
  q:[['What does the speaker suggest about the mountain?','It is patient and steady through every season.',['It is angry and loud.','It moves very fast.','It melts every summer.'],'Look at "does not hurry" and "patience".','The mountain is <b>patient and steady</b>.'],
     ['How does the second stanza build on the first?','It moves from winter to summer, showing the mountain through the seasons.',['It repeats the first stanza exactly.','It changes the topic to the ocean.','It tells a joke.'],'Compare the seasons in each stanza.','Stanza 1 is winter; stanza 2 is <b>summer</b>.'],
     ['What figurative language describes the mountain in the last line?','a metaphor calling it a giant',['a simile with like','an idiom about weather','no figurative language'],'Does it say "like a giant"?','"A giant full of dreams" is a <b>metaphor</b>.']]},
 {t:'Why the Bridge Closed (two reports)',p:['<b>Report A:</b> The Elm Street bridge closed Monday after engineers found cracks in two support beams. Repairs will take six weeks.','<b>Report B:</b> Drivers on Elm Street now face a 20-minute detour. Local shops say fewer customers are coming because of the closed bridge.'],
  q:[['How is the focus of Report A different from Report B?','A explains why the bridge closed; B describes how the closing affects people.',['A is about shops; B is about cracks.','Both only describe cracks.','Both are opinions.'],'Look at what each report emphasizes.','Report A: <b>the cause</b>. Report B: <b>the effects</b>.'],
     ['If you combine both reports, what do you learn?','Cracks closed the bridge for six weeks, causing detours and fewer shoppers.',['The bridge will never reopen.','Shops caused the cracks.','Drivers like the detour.'],'Put the information together.','Combining both: <b>cause, time and effects</b>.'],
     ['Which detail is a <b>fact</b>, not an opinion?','Repairs will take six weeks.',['The detour is the worst thing ever.','The bridge was ugly anyway.','Everyone hates Mondays.'],'A fact can be checked.','<b>Repairs will take six weeks</b> can be checked.']]},
 {t:'Grandfather\'s Garden',p:['Lucas thought gardening was boring until Grandfather handed him a seed no bigger than a freckle.','"This will become a pumpkin as big as your head," Grandfather said.','Lucas doubted it, but he watered the seed every day.','By October, he needed a wagon to carry his pumpkin to the fair.'],
  q:[['How does Lucas change in the story?','He goes from bored and doubtful to dedicated.',['He goes from happy to angry.','He does not change.','He becomes afraid of plants.'],'Compare the beginning and the end.','He thought gardening was boring, but he <b>watered it every day</b>.'],
     ['What is the meaning of the simile "no bigger than a freckle"?','The seed is very tiny.',['The seed is brown.','The seed has spots.','The seed is on his face.'],'How big is a freckle?','A freckle is tiny, so the seed is <b>very small</b>.'],
     ['Which detail shows the pumpkin grew very large?','He needed a wagon to carry it.',['He watered it every day.','It was October.','Grandfather handed him a seed.'],'Look at the last sentence.','<b>A wagon</b> was needed to carry it.']]},
 {t:'Bats Are Good Neighbors (an opinion)',p:['Many people fear bats, but bats are helpful neighbors.','A single bat can eat thousands of mosquitoes in one night.','Some bats also pollinate plants, such as the agave used to make many foods.','Instead of chasing bats away, communities should build bat houses.'],
  q:[['What is the author\'s main claim?','Communities should welcome and protect bats.',['Bats are scary.','Mosquitoes are helpful.','Agave is a fruit.'],'Look at the first and last sentences.','The author argues <b>bats are helpful and should be protected</b>.'],
     ['Which evidence best supports the claim?','A single bat can eat thousands of mosquitoes in one night.',['Many people fear bats.','Bats fly at night.','Bat houses are wooden.'],'Which detail shows bats help people?','Eating mosquitoes shows bats <b>help people</b>.'],
     ['How does the author address people who disagree?','by admitting many fear bats, then giving reasons bats help',['by ignoring them','by calling them names','by agreeing bats are bad'],'Look at the first sentence.','The author <b>acknowledges the fear, then answers it</b>.']]},
 {t:'A Tale of Two Mice (two fables)',p:['<b>Fable 1:</b> A city mouse visited a country mouse and laughed at his plain food. But in the city, a cat chased them both. "I prefer my plain food in peace," said the country mouse.','<b>Fable 2:</b> A rich crow stole bread from a busy market every day but was always chased by dogs. A sparrow ate seeds in a quiet field. "Better a little with peace," sang the sparrow.'],
  q:[['What theme do both fables share?','A simple, peaceful life is better than a rich, dangerous one.',['Cities are always better.','Animals should share bread.','Cats and dogs are friends.'],'Compare what the country mouse and sparrow say.','Both say <b>peace matters more than riches</b>.'],
     ['How are the two fables structured alike?','Each contrasts a risky life with a calm one and ends with a lesson.',['Both are told as poems.','Both have no characters.','Both end with a question.'],'Look at how each story is built.','Each <b>compares two ways of living and ends with a lesson</b>.'],
     ['Which character in Fable 2 is most like the country mouse?','the sparrow',['the crow','the dogs','the market'],'Who prefers peace?','The <b>sparrow</b>, like the country mouse, prefers peace.']]}
];
