const LONG5Q=LONG5.flatMap((P,pi)=>P.q.map((_,qi)=>[pi,qi]));
function genLong5(pi,qi){const P=LONG5[pi],Q=P.q[qi],base={visual:longHTML(P),wide:true,longp:true,speak:`${P.t}. ${P.p.join(' ')}`.replace(/<[^>]+>/g,'')};
  if(Q[0]==='mc'){const [,pr,a,w,h,e]=Q;return {...base,prompt:pr,...strChoices(a,shuffle(w.slice())),hint:h,explain:e,long:true,render:c=>esc(c),speak:base.speak+' Question: '+pr.replace(/<[^>]+>/g,'')}}
  if(Q[0]==='ab'){const [,pa,aa,wa,pb,ab,wb,h,e]=Q;return {...base,kind:'partab',prompt:'Answer <b>both</b> parts.',a:{prompt:pa.replace(/^<b>Part A:<\/b>\s*/,''),choices:shuffle([aa,...wa]),answer:aa},b:{prompt:pb.replace(/^<b>Part B:<\/b>\s*/,''),choices:shuffle([ab,...wb]),answer:ab},hint:h,explain:e}}
  if(Q[0]==='two'){const [,pr,rs,ws,h,e]=Q,all=shuffle([...rs,...ws]);return {...base,kind:'multi',oneCol:true,items:all.map((x,i)=>({id:'o'+i,html:`<span class="tsent">${esc(x)}</span>`,name:x,txt:true})),correct:all.map((x,i)=>rs.includes(x)?'o'+i:null).filter(Boolean),prompt:pr+' <span class="pick2">Choose two.</span>',hint:h,explain:e}}
  const [,pr,sub,h,e]=Q,hit=lpSentences(P).flat().filter(x=>x.s.includes(sub)).map(x=>x.i);return {...base,kind:'hilite',prompt:pr,hl:hit,sentText:sub,hint:h,explain:e}}

/* text features and multiple sources (RI.5.5, RI.5.7) */
const TF5PAGE=`<div class="passage tfpage"><h4>The Gold Rush</h4><h5>Gold at Sutter's Mill</h5><p>In January 1848, James Marshall found gold at Sutter's Mill in California. News spread quickly.</p><h5>The Forty-Niners</h5><p>By 1849, about 90,000 people had arrived. They were called "forty-niners."</p><div class="note" style="background:#fff6d6;border-radius:12px;padding:8px 12px"><b>Sidebar: Did you know?</b> Many forty-niners made more money selling supplies than finding gold.</div><p class="note"><b>Timeline</b> &nbsp; 1848: gold found &nbsp;·&nbsp; 1849: forty-niners arrive &nbsp;·&nbsp; 1850: California becomes a state</p><p class="note"><b>Sources:</b> California State Library; Gold Rush diaries</p></div>`;
